export type LinkState =
  | 'loading'
  | 'code'
  | 'expired'
  | 'no_integration'
  | 'rate_limited'
  | 'error';

interface ErrorBody {
  error_code?: string;
  error?: string;
  message?: string;
}

function readBody(e: unknown): ErrorBody {
  return e && typeof e === 'object' ? (e as ErrorBody) : {};
}

export function extractMessage(e: unknown): string {
  const b = readBody(e);
  return b.error || b.message || '';
}

export function deriveErrorState(e: unknown): LinkState {
  const body = readBody(e);
  if (body.error_code === 'no_active_teams_integration') return 'no_integration';
  if (body.error_code === 'active_link_codes_exist') return 'rate_limited';

  // TODO(DOCB-10603): drop the string-match fallback once backend ships
  // error_code to prod. Tracked in the handler spec for
  // POST /integrations/teams/link-code.
  const msg = body.error || body.message || '';
  if (/no active teams integration/i.test(msg)) return 'no_integration';
  if (/active link codes/i.test(msg)) return 'rate_limited';

  return 'error';
}

export function formatCountdown(countdownSeconds: number): string {
  const m = Math.floor(countdownSeconds / 60);
  const s = countdownSeconds % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

export function buildLinkCommand(code: string): string {
  return `/link ${code}`;
}

export function secondsFromExpiry(expiresAt: number, now: number): number {
  return Math.max(0, Math.round((expiresAt - now) / 1000));
}
