<template>
  <div class="teams-link-code-page">
    <div class="link-card rounded-xl border p-6">
      <div class="mb-4 flex items-center gap-3">
        <Icon icon="mdi:microsoft-teams" class="size-8 text-primary" />
        <div>
          <h2 class="text-lg font-semibold">
            {{ $t('teams_link_code_title') }}
          </h2>
          <p class="text-sm text-muted-foreground">
            {{ $t('teams_link_code_subtitle') }}
          </p>
        </div>
      </div>

      <!-- Loading -->
      <div
        v-if="state === 'loading'"
        class="flex items-center gap-2 py-6 text-sm text-muted-foreground"
      >
        <q-spinner size="16px" />
        {{ $t('generating_code') }}
      </div>

      <!-- Code display -->
      <div v-else-if="state === 'code'" class="flex flex-col gap-4">
        <div class="flex items-center gap-3">
          <code
            class="flex-1 rounded-lg bg-muted px-4 py-3 text-center text-2xl font-bold tracking-widest"
          >
            {{ code }}
          </code>
          <q-btn flat round dense @click="copyCode">
            <Icon icon="mdi:content-copy" class="size-5" />
            <q-tooltip>{{ $t('copy') }}</q-tooltip>
          </q-btn>
        </div>

        <div class="flex items-center gap-2 text-xs text-muted-foreground">
          <Icon icon="mdi:clock-outline" class="size-3.5" />
          <span>{{ $t('expires_in') }} {{ countdownDisplay }}</span>
        </div>

        <div class="rounded-lg border bg-muted/30 p-3 text-sm">
          <div class="mb-1 font-medium">{{ $t('instructions') }}</div>
          <ol class="list-decimal space-y-1 pl-5 text-muted-foreground">
            <li>{{ $t('teams_link_step_open_teams') }}</li>
            <li>
              {{ $t('teams_link_step_send_command', { command: linkCommand }) }}
            </li>
            <li>{{ $t('teams_link_step_done') }}</li>
          </ol>
        </div>
      </div>

      <!-- Expired -->
      <div v-else-if="state === 'expired'" class="flex flex-col gap-3 py-4">
        <div class="flex items-center gap-2 text-sm text-warning">
          <Icon icon="mdi:clock-alert-outline" class="size-5" />
          {{ $t('connect_code_expired') }}
        </div>
        <div class="flex gap-2">
          <q-btn
            outline
            dense
            color="primary"
            :label="$t('retry')"
            @click="generateCode"
          />
          <q-btn
            flat
            dense
            :label="$t('back_to_docnet')"
            @click="goBackToDocNet"
          />
        </div>
      </div>

      <!-- Not connected -->
      <div
        v-else-if="state === 'no_integration'"
        class="flex flex-col gap-3 py-4"
      >
        <div class="flex items-center gap-2 text-sm">
          <Icon icon="mdi:alert-circle-outline" class="size-5 text-warning" />
          <span class="font-medium">
            {{ $t('teams_link_no_integration_title') }}
          </span>
        </div>
        <p class="text-sm text-muted-foreground">
          {{ $t('teams_link_no_integration_body') }}
        </p>
        <q-btn
          flat
          dense
          :label="$t('back_to_docnet')"
          class="self-start"
          @click="goBackToDocNet"
        />
      </div>

      <!-- Rate limited -->
      <div
        v-else-if="state === 'rate_limited'"
        class="flex flex-col gap-3 py-4"
      >
        <div class="flex items-center gap-2 text-sm">
          <Icon icon="mdi:timer-sand" class="size-5 text-warning" />
          <span class="font-medium">
            {{ $t('teams_link_rate_limited_title') }}
          </span>
        </div>
        <p class="text-sm text-muted-foreground">
          {{ $t('teams_link_rate_limited_body') }}
        </p>
        <q-btn
          flat
          dense
          :label="$t('back_to_docnet')"
          class="self-start"
          @click="goBackToDocNet"
        />
      </div>

      <!-- Generic error -->
      <div v-else-if="state === 'error'" class="flex flex-col gap-3 py-4">
        <div class="flex items-center gap-2 text-sm text-negative">
          <Icon icon="mdi:alert-outline" class="size-5" />
          {{ errorMessage || $t('integration_error_generate_code') }}
        </div>
        <div class="flex gap-2">
          <q-btn
            outline
            dense
            color="primary"
            :label="$t('retry')"
            @click="generateCode"
          />
          <q-btn
            flat
            dense
            :label="$t('back_to_docnet')"
            @click="goBackToDocNet"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import { copyToClipboard, Notify } from 'quasar';
import DocNetIntegrationService from 'src/services/docnet/DocNetIntegrationService';
import {
  buildLinkCommand,
  deriveErrorState,
  extractMessage,
  formatCountdown,
  secondsFromExpiry,
  type LinkState,
} from './teams-link-code.utils';

export default defineComponent({
  name: 'TeamsLinkCodePage',

  components: { Icon },

  data() {
    return {
      service: new DocNetIntegrationService(),
      state: 'loading' as LinkState,
      code: '',
      countdownSeconds: 0,
      expiresAt: 0,
      countdownTimer: null as ReturnType<typeof setInterval> | null,
      errorMessage: '',
    };
  },

  computed: {
    countdownDisplay(): string {
      return formatCountdown(this.countdownSeconds);
    },
    linkCommand(): string {
      return buildLinkCommand(this.code);
    },
  },

  mounted() {
    this.generateCode();
  },

  beforeUnmount() {
    this.clearTimer();
  },

  methods: {
    async generateCode() {
      this.clearTimer();
      this.state = 'loading';
      this.errorMessage = '';
      try {
        const result = await this.service.generateTeamsLinkCode();
        this.code = result.code;
        this.expiresAt = Date.now() + result.expires_in_seconds * 1000;
        this.countdownSeconds = result.expires_in_seconds;
        this.state = 'code';
        this.startCountdown();
      } catch (e: unknown) {
        this.state = deriveErrorState(e);
        if (this.state === 'error') {
          this.errorMessage = extractMessage(e);
        }
      }
    },

    startCountdown() {
      this.countdownTimer = setInterval(() => {
        this.countdownSeconds = secondsFromExpiry(this.expiresAt, Date.now());
        if (this.countdownSeconds <= 0) {
          this.clearTimer();
          this.state = 'expired';
        }
      }, 1000);
    },

    clearTimer() {
      if (this.countdownTimer) {
        clearInterval(this.countdownTimer);
        this.countdownTimer = null;
      }
    },

    copyCode() {
      copyToClipboard(this.linkCommand)
        .then(() =>
          Notify.create({
            type: 'positive',
            message: this.$t('copied') as string,
            position: 'top',
          }),
        )
        .catch(() =>
          Notify.create({
            type: 'negative',
            message: this.$t('copy_failed') as string,
            position: 'top',
          }),
        );
    },

    goBackToDocNet() {
      this.$router.push('/doc-net');
    },
  },
});
</script>

<style lang="scss" scoped>
.teams-link-code-page {
  max-width: 560px;
  margin: 0 auto;
  padding: 16px 0;
}

.link-card {
  background: var(--dashboard-surface-color, #fff);
}
</style>
